# Parse the edges from the context
edges_text = context.split("The graph has the following edges:")[1].split("Operation:")[0].strip()

edges = []
for line in edges_text.strip().split('\n'):
    if '->' in line:
        source, target = line.split('->')
        edges.append((source.strip(), target.strip()))

print("Parsed edges:")
for e in edges:
    print(f"  {e[0]} -> {e[1]}")

target_node = "c4ca4238a0"
parents = set()

for source, target in edges:
    if target == target_node:
        parents.add(source)

print(f"\nParents of {target_node}: {sorted(parents)}")
